FeatureDefinition.Code:
public string Get_Feature_Rezerwa_MPK(Context cx) {
	// MPK = centrum kosztów z wydziału pracownika na datę aktualności listy.
	// Gdy wydział nie ma przypisanego centrum kosztów - bierze centrum z wydziału nadrzędnego.
	Date data = ActualDate.Today(cx);

	PracHistoria ph = ((Pracownik)Row)[data];
	if (ph == null)
		return "";
	Wydzial w = ph.Etat.Wydzial;
	while (w != null && w.CentrumKosztow == null)
		w = w.Nadrzedny;
	if (w == null)
		return "";
	return w.CentrumKosztow.ToString();
}

public decimal Get_Feature_Rezerwa_urlop_zaległy(Context cx) {
	// Kolumna widoku rezerwy urlopowej na liście Pracownicy.
	// Miesiąc rezerwy = miesiąc daty aktualności listy.
	Date data = ActualDate.Today(cx);

	// Ostatnio naliczona pozycja elementu "Rezerwa urlopowa" pracownika na planowanej liście płac za ten miesiąc
	PlaceModule place = PlaceModule.GetInstance(Session);
	PlanowanyElementWypłaty e = null;
	foreach (PlanowanyElementWypłaty p in place.PlanElementyWyp.WgPracownik[(Pracownik)Row]) {
		if (p.Definicja == null || p.Definicja.Nazwa != "Rezerwa urlopowa")
			continue;
		if (p.Okres.To.Year != data.Year || p.Okres.To.Month != data.Month)
			continue;
		if (e == null || p.ID > e.ID)
			e = p;
	}
	if (e == null)
		return 0m;
	return System.Math.Round((decimal)e.Podstawa3.Value, 2);
}

